// AMD module for the mod_fastpix activity edit form upload widget.
// AMD-wrapped (define()) — produced manually since the dev environment
// lacks grunt amd. Replace via `grunt amd` once available.
//
// Phase C UI redesign:
// - Pill-toggle (rendered by mod_form HTML) drives the hidden <select name="source_type">.
// - Drop zone replaces the file-input + Start-upload pair. Click or drop both
//   trigger the hidden <input type="file">. Selecting a file auto-starts the upload.
// - Post-upload preview row replaces the inline alert on success.

define(['core/ajax', 'core/notification', 'core/templates'], function(Ajax, Notification, Templates) {
    'use strict';

    var SELECTORS = {
        region:           '[data-region="fastpix-upload-widget"]',
        picker:           '[data-region="fastpix-upload-picker"]',
        dropzone:         '[data-region="fastpix-upload-dropzone"]',
        input:            '[data-region="fastpix-upload-input"]',
        progressWrap:     '[data-region="fastpix-upload-progress"]',
        progressBar:      '[data-region="fastpix-upload-bar"]',
        progressBarFill:  '[data-region="fastpix-upload-bar-fill"]',
        progressPct:      '[data-region="fastpix-upload-percent"]',
        status:           '[data-region="fastpix-upload-status"]',
        urlSection:       '[data-region="fastpix-urlpull-section"]',
        urlStatus:        '[data-region="fastpix-urlpull-status"]',
        urlPreview:       '[data-region="fastpix-urlpull-preview"]',
        urlPreviewUrl:    '[data-region="fastpix-urlpull-preview-url"]',
        sourceType:       '[name="source_type"]',
        sourceUrl:        '[name="source_url"]',
        validateBtn:      '[name="validate_url"]',
        sourceTab:        '[data-action="fastpix-source-tab"]'
    };

    var sessionField = null;
    var widgetRegion = null;

    var setStatus = function(message, kind) {
        if (!widgetRegion) { return; }
        var el = widgetRegion.querySelector(SELECTORS.status);
        if (!el) { return; }
        el.hidden = false;
        el.textContent = message;
        el.className = 'mt-3 small alert alert-' + kind;
    };

    var clearStatus = function() {
        if (!widgetRegion) { return; }
        var el = widgetRegion.querySelector(SELECTORS.status);
        if (!el) { return; }
        el.hidden = true;
        el.textContent = '';
        el.className = 'mt-3 small';
    };

    var setUrlStatus = function(message, kind) {
        var el = document.querySelector(SELECTORS.urlStatus);
        if (!el) { return; }
        el.textContent = message;
        var color = kind === 'success' ? 'success'
                  : kind === 'danger'  ? 'danger'
                  : 'body-secondary';
        el.className = 'text-' + color + ' small mt-1';
    };

    var putToSignedUrl = function(file, uploadUrl, onProgress) {
        return new Promise(function(resolve, reject) {
            // FastPix's signed-PUT bucket strips ACAO on the PUT response,
            // so the browser fires `error` even when bytes are accepted.
            // Treat "progress reached 100% then error fired" as success.
            var bytesUploaded = false;
            var xhr = new XMLHttpRequest();
            xhr.open('PUT', uploadUrl);
            xhr.upload.addEventListener('progress', function(e) {
                if (e.lengthComputable) {
                    var pct = Math.round((e.loaded / e.total) * 100);
                    if (pct >= 100) { bytesUploaded = true; }
                    onProgress(pct);
                }
            });
            xhr.upload.addEventListener('load', function() {
                bytesUploaded = true;
            });
            xhr.addEventListener('load', function() {
                if (xhr.status >= 200 && xhr.status < 300) {
                    resolve();
                } else if (xhr.status === 0 && bytesUploaded) {
                    resolve();
                } else {
                    reject(new Error('upload_failed_' + xhr.status));
                }
            });
            xhr.addEventListener('error', function() {
                if (bytesUploaded) { resolve(); return; }
                reject(new Error('upload_network_error'));
            });
            xhr.addEventListener('abort', function() {
                reject(new Error('upload_aborted'));
            });
            xhr.send(file);
        });
    };

    var showProgressUI = function() {
        if (!widgetRegion) { return; }
        var dropzone = widgetRegion.querySelector(SELECTORS.dropzone);
        if (dropzone) { dropzone.hidden = true; }
        var progress = widgetRegion.querySelector(SELECTORS.progressWrap);
        if (progress) { progress.hidden = false; }
    };

    var showSuccessUI = function(filename) {
        if (!widgetRegion) { return; }
        var progress = widgetRegion.querySelector(SELECTORS.progressWrap);
        if (progress) { progress.hidden = true; }
        setStatus('Uploaded ' + filename + '. Save the activity to finalise.', 'success');
    };

    var showDropzoneUI = function() {
        if (!widgetRegion) { return; }
        var dropzone = widgetRegion.querySelector(SELECTORS.dropzone);
        if (dropzone) { dropzone.hidden = false; }
        var progress = widgetRegion.querySelector(SELECTORS.progressWrap);
        if (progress) { progress.hidden = true; }
    };

    var handleFileSelected = function(file) {
        if (!file || !widgetRegion) { return; }
        clearStatus();
        showProgressUI();

        Ajax.call([{
            methodname: 'local_fastpix_create_upload_session',
            args: { filename: file.name, size: file.size }
        }])[0].then(function(session) {
            var bar = widgetRegion.querySelector(SELECTORS.progressBar);
            var fill = widgetRegion.querySelector(SELECTORS.progressBarFill);
            var pct = widgetRegion.querySelector(SELECTORS.progressPct);
            return putToSignedUrl(file, session.upload_url, function(percent) {
                if (bar) { bar.value = percent; }
                if (fill) { fill.style.width = percent + '%'; }
                if (pct) { pct.textContent = percent + '%'; }
            }).then(function() {
                if (sessionField) {
                    sessionField.value = String(session.session_id);
                }
                showSuccessUI(file.name);
            });
        }).catch(function(e) {
            showDropzoneUI();
            setStatus('Upload failed: ' + (e.message || 'unknown error'), 'danger');
            Notification.exception(e);
        });
    };

    var wireDropzone = function() {
        if (!widgetRegion) { return; }
        var dropzone = widgetRegion.querySelector(SELECTORS.dropzone);
        var input = widgetRegion.querySelector(SELECTORS.input);
        if (!dropzone || !input) { return; }

        dropzone.addEventListener('click', function(e) {
            if (e.target === input) { return; }
            input.click();
        });

        dropzone.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                input.click();
            }
        });

        var setDragging = function(on) {
            // Visual style is owned by the .is-dragging CSS rule in the template.
            if (on) {
                dropzone.classList.add('is-dragging');
            } else {
                dropzone.classList.remove('is-dragging');
            }
        };

        ['dragenter', 'dragover'].forEach(function(ev) {
            dropzone.addEventListener(ev, function(e) {
                e.preventDefault();
                e.stopPropagation();
                setDragging(true);
            });
        });
        ['dragleave', 'dragend'].forEach(function(ev) {
            dropzone.addEventListener(ev, function(e) {
                e.preventDefault();
                e.stopPropagation();
                setDragging(false);
            });
        });
        dropzone.addEventListener('drop', function(e) {
            e.preventDefault();
            e.stopPropagation();
            setDragging(false);
            var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
            if (file) {
                handleFileSelected(file);
            }
        });

        input.addEventListener('change', function() {
            var file = input.files && input.files[0];
            if (file) {
                handleFileSelected(file);
            }
        });
    };

    var validateUrl = function() {
        var urlInput = document.querySelector(SELECTORS.sourceUrl);
        if (!urlInput || !urlInput.value) {
            setUrlStatus('Enter a URL first.', 'warning');
            return;
        }
        setUrlStatus('Validating…', 'muted');

        Ajax.call([{
            methodname: 'local_fastpix_create_url_pull_session',
            args: { source_url: urlInput.value }
        }])[0].then(function(session) {
            if (sessionField) {
                sessionField.value = String(session.session_id);
            }
            // Reveal the urlpull-preview row and populate it with the URL value.
            // Use document-scoped queries so this still works regardless of
            // the preview wrapper's nesting depth.
            var slot = document.querySelector(SELECTORS.urlPreviewUrl);
            if (slot) { slot.textContent = urlInput.value; }
            var preview = document.querySelector(SELECTORS.urlPreview);
            if (preview) { preview.hidden = false; }
            setUrlStatus('✓ URL validated. Save the activity to finalize.', 'success');
        }).catch(function(e) {
            Notification.exception(e);
            setUrlStatus('URL rejected.', 'danger');
        });
    };

    var attachValidateHandler = function() {
        var validateBtn = document.querySelector(SELECTORS.validateBtn);
        if (!validateBtn) { return false; }
        if (validateBtn.getAttribute('data-fastpix-wired') === '1') { return true; }
        validateBtn.setAttribute('data-fastpix-wired', '1');
        validateBtn.addEventListener('click', function(e) {
            e.preventDefault();
            validateUrl();
        });
        return true;
    };

    var refreshTabVisibility = function() {
        var sourceType = document.querySelector(SELECTORS.sourceType);
        if (!sourceType) { return; }
        var isUpload = sourceType.value === 'upload';
        if (widgetRegion) {
            var picker = widgetRegion.querySelector(SELECTORS.picker);
            if (picker) { picker.hidden = !isUpload; }
        }
        var urlSection = document.querySelector(SELECTORS.urlSection);
        if (urlSection) { urlSection.hidden = isUpload; }
    };

    var refreshPillVisuals = function() {
        var sourceType = document.querySelector(SELECTORS.sourceType);
        if (!sourceType) { return; }
        var pills = document.querySelectorAll(SELECTORS.sourceTab);
        for (var i = 0; i < pills.length; i++) {
            var btn = pills[i];
            var active = btn.getAttribute('data-source-type') === sourceType.value;
            btn.setAttribute('aria-selected', active ? 'true' : 'false');
            if (active) {
                btn.classList.add('fw-medium');
                btn.classList.remove('text-body-secondary', 'border-0');
                btn.style.background = '#fff';
                btn.style.border = '1px solid #e5e7eb';
                btn.style.boxShadow = '0 1px 2px rgba(0,0,0,.05)';
            } else {
                btn.classList.add('text-body-secondary', 'fw-medium', 'border-0');
                btn.style.background = 'transparent';
                btn.style.border = '0';
                btn.style.boxShadow = 'none';
            }
        }
    };

    var wirePillToggle = function() {
        var sourceType = document.querySelector(SELECTORS.sourceType);
        if (!sourceType) { return; }
        var pills = document.querySelectorAll(SELECTORS.sourceTab);
        for (var i = 0; i < pills.length; i++) {
            (function(btn) {
                if (btn.getAttribute('data-fastpix-wired') === '1') { return; }
                btn.setAttribute('data-fastpix-wired', '1');
                btn.addEventListener('click', function(e) {
                    e.preventDefault();
                    var target = btn.getAttribute('data-source-type');
                    if (sourceType.value === target) { return; }
                    sourceType.value = target;
                    sourceType.dispatchEvent(new Event('change', {bubbles: true}));
                    refreshPillVisuals();
                });
            })(pills[i]);
        }
    };

    return {
        init: function(config) {
            sessionField = document.querySelector('input[name="' + config.fieldnameSession + '"]');
            widgetRegion = document.querySelector(SELECTORS.region);

            wirePillToggle();
            refreshPillVisuals();

            if (!attachValidateHandler()) {
                setTimeout(attachValidateHandler, 100);
            }

            // Invalidate the urlpull preview + cached session_id when the URL
            // is edited so a stale session can't be submitted against a new URL.
            var urlInputEl = document.querySelector(SELECTORS.sourceUrl);
            if (urlInputEl && urlInputEl.getAttribute('data-fastpix-wired') !== '1') {
                urlInputEl.setAttribute('data-fastpix-wired', '1');
                urlInputEl.addEventListener('input', function() {
                    var preview = document.querySelector(SELECTORS.urlPreview);
                    if (preview) { preview.hidden = true; }
                    if (sessionField) { sessionField.value = ''; }
                });
            }

            var sourceType = document.querySelector(SELECTORS.sourceType);
            if (sourceType) {
                sourceType.addEventListener('change', function() {
                    refreshTabVisibility();
                    refreshPillVisuals();
                });
            }

            if (!widgetRegion) { return; }

            Templates.renderForPromise('mod_fastpix/upload_widget', {}).then(function(result) {
                Templates.replaceNodeContents(widgetRegion, result.html, result.js);
                refreshTabVisibility();
                wireDropzone();
            }).catch(function(e) {
                Notification.exception(e);
            });
        }
    };
});
